package dev.akhras;import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.client.TestRestTemplate;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) class ContextTest{@Autowired TestRestTemplate http;@Test void authAndRefresh(){var registered=http.postForEntity("/auth/register",Map.of("email","integration@example.test","password","valid-password"),Map.class);assertEquals(200,registered.getStatusCode().value());String token=(String)registered.getBody().get("accessToken");String refresh=(String)registered.getBody().get("refreshToken");var headers=new HttpHeaders();headers.setBearerAuth(token);headers.setContentType(MediaType.APPLICATION_JSON);var account=http.exchange("/accounts",HttpMethod.POST,new HttpEntity<>(Map.of("name","Checking"),headers),Map.class);assertEquals(200,account.getStatusCode().value());assertEquals(200,http.postForEntity("/auth/refresh",Map.of("refreshToken",refresh),Map.class).getStatusCode().value());assertEquals(401,http.postForEntity("/auth/refresh",Map.of("refreshToken",refresh),Map.class).getStatusCode().value());}}